        K := 0.6;
        D1 := K * 0.84;
        D2 := K * 0.75;
        D3 := D1 - K * 0.2;
        D4 := D2 - K * 0.2;
        R1 := 0.2;
        R2 := 0.4;
        H := D1 * sqrt(2);

        N := 40;
        for i := 0 to N - 1 do begin
            A := 2*Pi / N * i;
            sa := sin(A);
            ca := cos(A);
            x1[i] := R1 * ca;
            y1[i] := R1 * sa;
            x2[i] := R2 * ca;
            y2[i] := R2 * sa;
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

